package com.quizmaster.filter;
import com.quizmaster.model.User;import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.IOException;
@WebFilter(urlPatterns={"/admin/*","/student/*"})public class AuthFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)a;HttpServletResponse p=(HttpServletResponse)b;HttpSession s=r.getSession(false);User u=s==null?null:(User)s.getAttribute("user");if(u==null){p.sendRedirect(r.getContextPath()+"/login");return;}if(r.getServletPath().startsWith("/admin/")&&!u.getRole().equals("ADMIN")||r.getServletPath().startsWith("/student/")&&!u.getRole().equals("STUDENT")){p.sendError(403);return;}p.setHeader("Cache-Control","no-store");chain.doFilter(a,b);}}
